\begin{prop}\ollabel{prop:stricttopartial}
If $R$ is a strict order on~$A$, then $R^+ = R \cup \Id{A}$ is a
partial order. Moreover, if $R$ is a strict linear order, then $R^+$ is 
a linear order.
\end{prop}

